(window.webpackJsonp=window.webpackJsonp||[]).push([[93],{528:function(t,s,v){"use strict";v.r(s);var _=v(11),e=Object(_.a)({},(function(){var t=this,s=t.$createElement,v=t._self._c||s;return v("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[v("p",[v("font",{attrs:{size:"5"}},[t._v("摘要：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("1、旧约中已经揭示了受膏者和耶和华的关系，他就是耶和华的代表。而路加告诉我们，这位拿撒勒人耶稣，就是基督、就是这位受膏者。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("2、马太福音的家谱，侧重从血缘上的关系；路加福音的家谱，记载的是名分上的关系。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("3、名分意味着一种权利义务关系。神对亚当这个儿子尽了做父亲的责任，而亚当却违背了自己做儿子的义务；神对耶稣这个儿子同样尽了做父亲的责任，而耶稣却成功了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("4、神安排耶稣受洗，是要他与神的百姓认同；而耶稣甘愿受洗，就表达了他认可他是属于神的众百姓中的一员，虽然他们都犯了罪；他进而也认可，他愿意来为神的众百姓的罪承担代价。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("5、在困难中我们之所以坚持信靠基督，是因为我们的脑子还没有坏。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们平安。前面两次我们都停留在路加福音3:1~20。第一次我们是从神的救赎历史的角度来看。上一次我们是从要如何获得神的救恩的角度来看。今天我们继续路加福音，我们来讲路加福音3章剩下的部分。我们今天分享的题目是：耶稣是谁。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这个问题对于基督徒，尤其是已经信主很多年的基督徒，是一个非常简单的问题。我们上过的各种慕道班、受洗班，参与过的各种查经团契、讲道，都在反复告诉我们耶稣是谁。因为对这个问题的回答，事关你最后的归宿是哪里。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但是今天呢，我不会就着信条或者系统神学提供的标准答案来分享这个话题，而是结合我们的经文，帮助大家从另外一些角度来认识一下我们的主耶稣。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("一、他是神的代表")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在路加福音3章16~17节，约翰提到：“我是用水给你们施洗。但有一位能力比我更大的要来，我就是给他解鞋带也不配，他要用圣灵与火给你们施洗。 他手里拿着簸箕，要扬净他的场，把麦子收在仓里，把糠用不灭的火烧尽了。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们已经说过，约翰是先知书中所预言的那个在旷野呼喊的人，他来是为了预备道路，所预备的道路就是人的心。那么他是为谁预备道路呢？让我们再来看一看以赛亚书40章3~5节说：有人声喊着说：“在旷野预备耶和华的路，在沙漠地修平我们神的道！一切山洼都要填满，大小山冈都要削平，高高低低的要改为平坦，崎崎岖岖的必成为平原。耶和华的荣耀必然显现，凡有血气的必一同看见，因为这是耶和华亲口说的。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以约翰是为谁预备道路呢？以赛亚书说是“预备耶和华的路”、“修平我们神的道”，很清楚，他是在为耶和华神预备道路。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("到了以赛亚书40：9~11节又说：“报好信息给锡安的啊，你要登高山！报好信息给耶路撒冷的啊，你要极力扬声！扬声不要惧怕，对犹大的城邑说：“看哪，你们的神！”主耶和华必像大能者临到，他的膀臂必为他掌权。他的赏赐在他那里，他的报应在他面前。他必像牧人牧养自己的羊群，用膀臂聚集羊羔抱在怀中，慢慢引导那乳养小羊的。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这里说当这个呼喊者完成他的使命，道路预备好了，“主耶和华”就会临到，他会来拯救他的羊群，他也会来施以报应、审判。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而在路加福音3:15~17节，施洗约翰说在他之后会来的是基督（上次我们说了，基督的意思就是“受膏者”），一位能力比他更大的，他要用圣灵与火给他们施洗。要扬净他的场，把麦子（也就是属于耶和华的人）收在仓里，把糠（也就是那些不属耶和华的人），用不灭的火烧尽了。也就是说，基督要来拯救神的羊群，他也会来施以报应、审判。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那么实际到来的是谁呢？路加在3章20~22节说到，当施洗约翰被关进监狱里，完成了他的历史使命，紧接着那个由童贞女马丽亚从圣灵而受孕、在伯利恒的马槽里出生、在圣殿被西面和先知亚拿认出来、使耶路撒冷的律法教师感到稀奇、顺服他的父母的拿撒勒人耶稣，登场了。也就是说，这位耶稣正是来拯救神的羊群、来施以报应、审判的那一位。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家看到没有，这里有三个概念：以赛亚所预言的是耶和华上帝；施洗约翰所预言的是受膏者基督；路加说实际来的是拿撒勒人耶稣。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("路加在这里告诉我们什么呢？一方面，他告诉我们，拿撒勒人耶稣就是基督，就是那位受膏者；另一方面，路加在这里即使没有直接宣告这一位拿撒勒人耶稣、这一位百姓所指望的受膏者就是耶和华神自己，但起码是在告诉我们，这位拿撒勒人耶稣和以色列的神耶和华之间，具有密不可分的关系，他所做的就是耶和华所做的、他所说的就是耶和华所说的、他所拯救的就是耶和华所拯救的，他所报应、审判的，就是耶和华所报应、审判的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以总结起来我们可以看到，拿撒勒人耶稣就是受膏者、基督，而基督就代表了耶和华上帝。这也正是诗篇第2篇的所描述的受膏者与耶和华的关系。我们一起来看一下诗篇第2篇。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“1外邦为什么争闹，万民为什么谋算虚妄的事？2世上的君王一齐起来，臣宰一同商议，要抵挡耶和华并他的受膏者，3说：“我们要挣开他们的捆绑，脱去他们的绳索！”4那坐在天上的必发笑，主必嗤笑他们。5那时，他要在怒中责备他们，在烈怒中惊吓他们，6说：“我已经立我的君在锡安我的圣山上了。”7受膏者说：“我要传圣旨。耶和华曾对我说：‘你是我的儿子，我今日生你。8你求我，我就将列国赐你为基业，将地极赐你为田产。9你必用铁杖打破他们，你必将他们如同窑匠的瓦器摔碎。’”10现在你们君王应当醒悟，你们世上的审判官该受管教！11当存畏惧侍奉耶和华，又当存战兢而快乐。12当以嘴亲子，恐怕他发怒，你们便在道中灭亡，因为他的怒气快要发作。凡投靠他的，都是有福的！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们来看诗篇第2篇第1~3节，这里描述外邦、万民、世上的君王臣宰谋算虚妄的事。他们要抵挡谁呢？耶和华和他的受膏者。这里体现出，耶和华和他的受膏者是联系在一起、密不可分的，都是这些人所要抵挡的对象。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("第4~6节，讲到那坐在天上的（也就是耶和华），他说你们这些谋算虚妄之事的人，都不是我真正君王，而那个真正的君王（指的那位受膏者），是我自己所选立的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而受膏者对自己的王权是怎么认识的呢？我们看第7节开始，受膏者说“我要传圣旨”。也就是说，他自己说自己是耶和华的使者、是耶和华的代表，他所说的其实都是耶和华说的，他所做的都是耶和华做的。第8~9节，这位受膏者说这个世界是耶和华所创造的，耶和华对其具有主权；他又立我为君王，把统治这个世界的主权也赐予给我，也就是认可我的统治就是神自己的统治。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以第4~9节这里同样说到耶和华和他的受膏者密不可分的关系，受膏者就是耶和华的代表。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("第10~12节，诗人劝诫这些世上的君王要醒悟，畏惧事奉耶和华。怎么做呢？要以嘴亲子，也就是以对受膏者的臣服之吻来表达他们内心对耶和华的降服，逃避他的愤怒。也就是说，臣服、事奉这位受膏者，就是畏惧事奉耶和华。这里同样表明了耶和华和他的受膏者密不可分的关系。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以我们看到，旧约中已经揭示了受膏者和耶和华的关系，他就是耶和华的代表。而路加告诉我们，这位拿撒勒人耶稣，就是基督、就是这位受膏者。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("二、他是神的儿子")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们再来看诗篇2:7，这里说“耶和华曾对我说：‘你是我的儿子，我今日生你。”我们看到这位受膏者不仅是神的代表，他也是神的儿子。是神的儿子意味着什么？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们回到路加福音第3章。在第3章23~38节，路加罗列了一个长长的家谱，告诉我们耶稣的谱系。如果我们去比较这个家谱与马太福音1~17节记载的耶稣的家谱，会发现这两者有很大的不同。对这些不同，学者们有很多研究。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("一般认为的是，马太福音记载的是一个以血统为特征的家谱。也许这就是为什么马太福音用的词是“某某人生某某人”这样的表达，表示一个血缘上的联系。在那个谱系中，即使两人之间不是亲生父子的关系，也至少是叔侄这样的近亲血缘关系。比如在马太福音1:12节说撒拉铁生所罗巴伯。如果我们去看历代志上3:17~19节就知道，实际上所罗巴伯的亲生父亲是毗大雅，而毗大雅是撒拉铁的弟弟。但在以斯拉记、尼希米记、和哈该书，都称所罗巴伯是撒拉铁的儿子，这很有可能是撒拉铁在生孩子之前就去世了，因此按照申命记25:5~6的要求，毗大雅与撒拉铁的妻子同房生下了所罗巴伯，归在撒拉铁名下。即使是这样，撒拉铁与所罗巴伯之间也是很近的血亲。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("既然马太福音记载的是一个血缘上的谱系，我们就可以理解为什么在1:16节，当马太记载了“雅各生约瑟”之后，并没有继续说约瑟生耶稣，而是仅仅是说约瑟只是马丽亚的丈夫，在生物血统上，耶稣只与马丽亚有关。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而在路加福音这里的家谱，重点不是记载血缘上的传承，而是强调名分上的关系。也许这就是为什么他没有用“某某人生某某人”这样的表达方式，而是说“某某人是某某人的儿子”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("路加福音3:23说耶稣“依人看来”，是约瑟的儿子。约瑟是马丽亚的丈夫，是耶稣的养父，那么当然依人看来，耶稣的在名分上是约瑟的儿子。后面说约瑟是希里的儿子。而马太福音说是雅各生了约瑟，这也不是矛盾。路加同样在这里强调的是约瑟和希里在名分上的关系。一般的教会传统对此的解释是，希里实际上是马丽亚的父亲，约瑟是他的女婿，因此从名分上，也可以说约瑟是希里的儿子。所以一般认为，马太是顺着约瑟的谱系记载，而路加是顺着马丽亚的谱系进行的记载。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("另一个重大的不同，是马太福音只记载到亚伯拉罕为止；而路加福音更往前追溯到亚当。在3:38最后，路加说“亚当是神的儿子”。神是个灵，是没有肉体存在的，因此他当然不会与亚当有什么血缘。这也同样说明，路加在这里记载的谱系，是强调一个名分的问题。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("名分意味着什么？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我举一个简单的例子。我生了我的儿子，因此在血缘上，我是他的父亲，他是我的儿子；在名分上也同样，我是他的父亲，他是我的儿子。假设我又去孤儿院里，办理收养手续，领养了一个孩子，那么这个孩子与我在血缘上并不是父子关系，但在名分上，我与这个孩子就成了父子关系；又假设后来这个孩子的亲生父母找到了，于是我与他解除了收养关系，这样在名分上，我和他也就不再是父子关系了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们还可以以耶稣和约瑟的关系举例。在血缘上，耶稣和约瑟之间并不是父子关系；但在名分上，因为约瑟是他的养父，因此他们之间是父子关系。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("从以上举的简单的例子大家可能已经想到，名分实际上意味着一种法律上的权利义务关系。重要的不是名分是如何产生的，而是产生了之后，双方对彼此就有了权利和义务。比如刚才我与那个被收养的孩子之间，当我们是父子关系时，意味着我对这个孩子有抚养的责任，这个孩子对我又赡养的义务，在我死后，这个孩子有继承我财产的权利；那么当我们解除了收养关系，没有了父子的名分，这个权利义务关系就没有了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("好，带着这样的理解，我们回到圣经。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("让我们再来看路加福音3:38这里说“亚当是神的儿子”。神的儿子，这是一个名分。这里说亚当是神的儿子，在诗篇第2:7说，受膏者是神的儿子，在路加福音第3：22节也说耶稣是神的儿子。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以我们要理解这份家谱中的最后一个人，也就是那位受膏者、那位拿撒勒人耶稣是“神的儿子”意味着什么，就要去看这份家谱中第一个人，亚当，他作为神的儿子意味着什么。刚才我们说了，这是一个名分，我们在这里不必去管这种名分是怎么产生的，重要的是，有了这个名分，就意味着一种权利义务关系。所以我们首先来看一看亚当和神之间的这种关系。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们来翻到创世记第1章28节，这里在圣经中第一次讲到神与亚当（当然这里也包括了夏娃，但亚当和夏娃实际上是一个共同体）之间的互动。1章28节这里先是说“神就赐福给他们”。具体怎么赐福的？这里没有说。然后耶和华对他们说话，先是赋予他们使命（创1:28），接着向他们承诺会供养他们的所需（创1:29）。如果说创世记第1章，主要还是在描述神对他的儿子亚当说了什么，那么第2章，我们就可以看到神对他的儿子亚当做了什么。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在创世记2:8节记载，神为亚当立了一个园子，把他安置在那里。换句话说，为他提供一个居所。2:9节记载，神使各样树从地上长出，可以悦人的眼目、也可以做食物。也就是说，为他身体的需要提供物质性的食物，同时也为他精神的需要提供艺术性的精神养料。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("到了第15节，耶和华开始赋予他一个小小的使命，就是修理、看守他自己的居所，伊甸园，并且在第16~17节给他立下行为的界限。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("接着在第18~22节，讲到神为他创造了一个配偶来陪伴、帮助他。我们来看这个过程。18节讲到耶和华自己主动顾惜到亚当的需要，认为他一个人独居不好。然后在19~20节，我们在这段经文中似乎是看到神把他的创造物一个一个带到他的儿子面前问他，“你觉得这个合适不？”；“你觉得那个合适不？”——让他自己选。不过亚当都没有遇见能帮助他的创造物。于是在21~22记载，神干脆为了他又创造了女人。而亚当也相当的爱她，因此说这是他的“骨中骨，肉中肉”（创2:23）。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果我们通过这些经文去重现神的创造历史，大概是在女人被创造之后，神才对他们说了创世记1:28~29节这些话，也就是赋予他们更大的使命。而之前，就是1:28节这里说的“神赐福给他们”的内容。所以神的赐福是什么呢？前面我们列出的包括：供应居所、供应食物、供应精神上愉悦、赋予一个小小的任务来训练他、设下规矩、提供自主选择的机会、提供人所需要的亲密同伴关系。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果你们读过任何一本育儿的书籍，你们就会知道，当一对父母对一个孩子尽到最理想的养育责任的时候，就是为他们提供这些。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("接下来，在创世记1:28~29，神赋予亚当更大的使命，就是生养众多，遍满地面，不仅仅是治理伊甸园，而是要治理整个受造界。并且承诺不会让他们无依无靠、独立去做，会在这个过程中供应他们所需要的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家注意这里，治理受造界，不仅意味着使命，也意味着神把他这份产业托付给亚当。这就好比是一个企业家，精心养育、训练他的儿子，最终目的是把这个家族的产业交给他来继承。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以我们看到，在这样的一个权利义务关系中，神作为亚当的父亲，他对他的儿子负有养育的责任，他也实际地尽到了他的责任；而亚当作为神的儿子，他享有被神养育的权利、享有获得神产业的权利，同时他也有执行神赋予的使命、遵守神所立的规矩的义务。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当然，如果我们继续看创世记第3章，我们就知道，亚当并没有尽到他作为神的儿子该尽的责任，他背叛了神，逾越了神所立的规矩。因此，这个名分被破坏了。但神作为他的父亲，对他仍有怜悯，因此在创世记3:15节，神承诺会安排一个“女人的后裔”，打破蛇的权势，将亚当和他的后裔从与神之间破坏的关系中恢复过来；在3：21，神用皮子做衣服给他遮盖身体；在3：22节，神禁止他们吃生命树的果子，以避免他们永远活在败坏的肉体中受苦；在创世记4：6，神对亚当那败坏的儿子该隐做出善意的警告；在创世记4:15~16，神虽因该隐杀死亚伯而惩罚他但仍保全他的性命；在创世记4:25，神重新给亚当立一个儿子塞特；在创世记第5章，神让亚当的儿子继续繁衍生息；在创世记第6~7章，即使面对亚当众子的败坏，神仍然存留挪亚一家的性命，让亚当的后裔可以在他的创造中继续存活，并且生生不息。即使到了今天，亚当的后裔已经故意忘了谁是神，甚至说没有神，或者对神冷嘲热讽，但神仍然在施以宽容和怜悯，照样使阳光雨露降在地上，照样使一年四季周而复始。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以亚当作为神的儿子失败了，他的后裔们也都失败了。在路加福音3:24~38节这段长长的名单当中，从亚当到约瑟，都失败了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但在这份名单中出现的这第一个名字耶稣，路加在这卷书的第1章就告诉我们，他实际上不是约瑟的儿子，因而也不是亚当的后裔。他是童贞女马丽亚从圣灵感孕而生，是女人的后裔而不是男人的后裔。所以3：24节，路加说“从人来看，他是约瑟的儿子”；但在前面的第22节，路加说从神来说，他是神的儿子；是独立于亚当的，另一个神的儿子。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("耶稣是神的儿子，这就意味着，神作为耶稣的父亲，他对他负有养育的责任；神实际一直在养育他。他使用马丽亚、约瑟来供应耶稣的起居、饮食；马太福音记载当的希律王想要杀他时，神在梦中告诉约瑟逃往埃及；神也从小事上训练他，让他一切以天父的事为念；也通过摩西的律法给他设立规矩。路加在这卷福音书的2:40节这样总结他之前的生活：神的恩在他身上。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在今天的经文中，他开始执行神赋予他更重要的使命之前，神也说“这是我的爱子，我喜悦你”——神也保证在这个过程中会供应他的需要。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当然，作为是神的儿子，他享有被神养育的权利、他将承受神的产业，也意味着同时他也有执行神赋予的使命、遵守神所立的规矩的义务。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("神的这个儿子，他是成功了还是失败了呢？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在今天的经文中，路加并没有告诉我们。但我想我们每个人都已经知道答案了。保罗在腓立比书2:8说“他存心顺服，以至于死，且死在十字架上”；希伯来书4:4节说“他也曾凡事受过试探，与我们一样，只是他没有犯罪。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("他成功了！在腓立比书，保罗接着说：“所以（注意这个因果关系的连词），神将他升为至高，又赐给他那超乎万名之上的名，叫一切在天上的、地上的、和地底下的，因耶稣的名无不屈膝，无不口称‘耶稣基督为主’”。耶稣自己也说：“天上地下所有的权柄都赐给我了”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("耶稣是神的儿子，但他不像亚当这个儿子。他们都被神所爱和供养，但耶稣履行了神一切使命、遵守了神一切规矩，因此他被神升为至高、他承受了神的产业。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("好了，那这与你有什么关系？与我又什么关系？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("三、神百姓的代表")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("让我们现在回到路加福音3:21~22节。这里讲到耶稣受洗。这里的洗礼，就是第3节所说，约翰所宣讲的“悔改的洗礼”。神的百姓，因为都是亚当的后裔，所以也是败坏的和有罪的，当他们听到了约翰所传的神的话——也就是要认罪悔改、等待神的拯救，心里就会对这个话起反应，为自己的罪感到后悔，生发悔改的心。这是一个内心的状态，那么如何把这样的内心的状态表达出来呢？第一个表达就是接受悔改的洗礼，之后当然还包括了我们上次已经讲的实际地改变自己的行为，也就是结出果子来。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但耶稣作为独立于亚当的神的儿子，他并没有犯过罪，那为什么也要接受这个“悔改的洗礼”呢？马太福音3:13~15节告诉了我们答案。那里写到，耶稣要受约翰的洗，约翰却加以阻拦。而耶稣说：“你暂且许我，因为我们理当尽这诸般的义。”这句话的意思是：耶稣承认，按照这洗礼的实质——也就是，受洗的人认罪悔改之心的外在表达——他确实不应该受约翰的洗；但他接受洗，并不是按照这个洗礼的实质，而是要完成在救恩历史的这个时间点上（所以说是“暂且”），神的一个安排（这就是“要尽诸般的义”的含义）。而这个安排需要“我们”，也就是耶稣和约翰一同来完成，所以他告诉约翰不要阻止他受洗。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以对于耶稣而言，这个洗礼不意味着他内心的认罪悔改。那意味着什么呢？在他的事工开始之前，神安排他这个时候来受这个洗礼，目的是什么呢？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("路加福音3:21节这里其实给了我们一些暗示。这里说“众百姓受了洗，耶稣也受了洗”。众百姓中的每个人是要表达自己的认罪悔改心，那耶稣要表达什么呢？他在这里要表达的，是他与神的众百姓相认同。他认可他是属于神的众百姓中的一员，虽然他们都犯了罪；他进而也认可，他愿意来为神的众百姓的罪承担代价。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以，在救恩历史的这个时间点上，神要耶稣通过受洗来表明自己内心与神的百姓认同、接受自己是神的百姓的代表这样的身份。他虽然自己没有罪，但他代表着神的百姓认罪悔改，也将会代表着神的百姓承担罪的代价。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以我们可以看到，耶稣是神的百姓的代表。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而作为代表，耶稣不仅与他们认同、愿意替百姓们负上罪的代价，同时他也是神的百姓们的范式。他的生命状态、他与神的关系，也是神的百姓们应该、能够并且最终会成为的样子。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们再来看路加福音3：22节，这里说圣灵降在他身上，并且神确认耶稣的名分：这是我的爱子，我喜悦他。因此同样，耶稣所代表的神的百姓，也会从神那里领受圣灵，也会被神确认，这是我的儿子，我喜悦你。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以耶稣是神那个成功的儿子，他获得了天上地下所有的权柄，这与我有什么关系？这取决于我是不是被他代表。如果我被他代表，那么他的成功也就是我的成功；赐给他的权柄、产业，也赐给我；如果我不被他代表，那么他必用他的权柄代表神对我施行公义的审判。所以诗篇2的诗人才奉劝我们：当以嘴亲子，恐怕他发怒，你们便在道中灭亡，因为他的怒气快要发作。而接下来最后一句话说，“凡投靠他的，都是有福的。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，今天我们根据这段经文，从三个层面介绍了拿撒勒人耶稣是谁。当他面对我们的时候，他代表着神，我们看到他，就是看到了神。当他面对神的时候，他代表着我们，神透过他来看我们。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家现在因为信仰的原因受到一些逼迫，正在经历一段信仰上的艰难时期。上一周我们在分享的时候，有一个姐妹也说，自己不断在问自己，到底为什么要坚持这个信仰。是呀，为什么呢？今天的信息也许能从一个角度给我们提供一个答案：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("因为我们的头脑还是正常的。拿撒勒人耶稣他是神的代表，他是神成功的儿子，而他却愿意与我们认同、为我们负上代价，让我们与他的成功有份；那么除了认同他、感谢他、紧紧抓住他之外，其他的任何选择都是疯狂的。感谢主，我们的头脑还是正常的。")])],1)])}),[],!1,null,null,null);s.default=e.exports}}]);